/* KolibriOS for ARM: the Wi-Fi's regulatory domain (regd.c;
 * docs/pro1x-network.md), as Linux sets it for the WCN3990: ath's
 * regd.c (ath_regd_init: the EEPROM's code from SERVICE_READY, a world
 * domain or a country, the domain pair and its conformance test limits
 * for WMI_PDEV_SET_REGDOMAIN) and cfg80211's reg.c (the channels: ath's
 * custom world rules or the EEPROM's country as the base, the configured
 * country on top, as a user's hint: passive, radar, the power, HT40).
 * The tables are regdb.c, generated by tools/gen-regdb.py from Linux's
 * regd_common.h and wireless-regdb's regulatory.db. */
#ifndef REGD_H
#define REGD_H
#include "modem.h"

/* ath's (regd.h, regd_common.h) */
#define ATH_COUNTRY_ERD_FLAG 0x8000
#define ATH_WORLDWIDE_ROAMING_FLAG 0x4000
#define ATH_WORLD_SKU_MASK 0x00f0
#define ATH_WORLD_SKU_PREFIX 0x0060
#define ATH_WORLD 0x0199
#define ATH_CTRY_DEFAULT 0
#define ATH_CTRY_UNITED_STATES 840
#define ATH_CTRY_INDIA 356
#define ATH_NO_ENUMRD 0
#define ATH_NO_CTL 0xff

struct ath_regpair { u16 reg_domain, ctl_5g, ctl_2g; };
struct ath_country { u16 code, regdmn; char iso[3]; };
extern const struct ath_regpair ath_regpairs[];
extern const u32 ath_nregpairs;
extern const struct ath_country ath_countries[];
extern const u32 ath_ncountries;

/* wireless-regdb (cfg80211's struct fwdb_rule, its flags) */
#define FWDB_NO_OFDM 0x01
#define FWDB_NO_OUTDOOR 0x02
#define FWDB_DFS 0x04
#define FWDB_NO_IR 0x08
#define FWDB_AUTO_BW 0x10
struct regdb_rule { u32 start_khz, end_khz, max_bw_khz; u16 eirp_mbm; u8 flags; };
struct regdb_country { char alpha2[3]; u8 dfs_region, nrules; u16 first; };
extern const struct regdb_rule regdb_rules[];
extern const struct regdb_country regdb_countries[];
extern const u32 regdb_ncountries;

/* a channel's flags (cfg80211's IEEE80211_CHAN_*, the ones used here) */
#define REGD_DISABLED 0x001
#define REGD_NO_IR 0x002
#define REGD_RADAR 0x008
#define REGD_NO_HT40PLUS 0x010
#define REGD_NO_HT40MINUS 0x020
#define REGD_NO_HT40 (REGD_NO_HT40PLUS | REGD_NO_HT40MINUS)
#define REGD_NO_OFDM 0x040
#define REGD_NO_80MHZ 0x080
#define REGD_NO_160MHZ 0x100
#define REGD_INDOOR_ONLY 0x200
#define REGD_NO_20MHZ 0x800

#define REGD_MAX_CHANS 41               /* ath10k's 14 + 27 (ATH10K_NUM_CHANS) */
struct regd_chan {
	u16 freq, chan;
	u32 flags, orig_flags;
	s8 max_power, max_reg_power, orig_mpwr;   /* dBm */
};

struct regd {
	u16 eeprom;                     /* SERVICE_READY's (the low 16 bits, as ath10k_mac_init_rd) */
	u16 current_rd, country_code;   /* ath's (struct ath_regulatory) */
	struct ath_regpair pair;        /* for WMI_PDEV_SET_REGDOMAIN */
	char alpha2[3];                 /* ath's (the EEPROM's country, "00" for a world domain) */
	char user[3];                   /* the configured country ("" for none) */
	u8 dfs_region;                  /* the configured country's (1 FCC, 2 ETSI, 3 JP) */
	bool world, user_found;
	u32 nchan;
	struct regd_chan ch[REGD_MAX_CHANS];
};

/* ath_regd_init for the EEPROM's code, then the channels as cfg80211 has
 * them with the configured country (two letters, "" or "00" for none)
 * and ath10k_mac_update_channel_list's 5 GHz range (0 0: all): 0, or -1
 * (*why: the EEPROM's code is not one of ath's) */
int regd_init(struct regd *r, u32 eeprom_rd, const char *country, u16 low_5ghz, u16 high_5ghz, const char **why);
const struct regd_chan *regd_find(const struct regd *r, u16 freq);
const struct regdb_country *regdb_find(const char *alpha2);

#endif
